//! Runtime support for Rust code generated by py2rs: Python's printing,
//! arithmetic, string and list semantics, and its error messages.

use std::cmp::Ordering;
use std::fmt;
use std::io::{BufRead, Write};

pub use indexmap::{IndexMap, IndexSet};

pub mod err;
pub mod math;
pub mod spec;
pub mod strs;

pub use err::*;
pub use strs::*;

// ------------------------------------------------------------------ errors

/// Raise an uncaught Python exception: print it like CPython and exit with 1.
pub fn raise(exc: &str, msg: &str) -> ! {
    let _ = std::io::stdout().flush();
    eprintln!("Traceback (most recent call last):");
    if msg.is_empty() {
        eprintln!("{}", exc);
    } else {
        eprintln!("{}: {}", exc, msg);
    }
    std::process::exit(1)
}

fn exception_of(msg: &str) -> String {
    let first = msg.split(':').next().unwrap_or("");
    if !first.is_empty()
        && first.chars().all(|c| c.is_ascii_alphanumeric())
        && (first.ends_with("Error") || first.ends_with("Exception"))
    {
        return msg.to_string();
    }
    if msg.starts_with("attempt to") && msg.contains("overflow") {
        return "OverflowError: integer overflow (py2rs: int is a 64-bit integer)".into();
    }
    if msg.contains("index out of bounds") {
        return "IndexError: list index out of range".into();
    }
    if msg.contains("divide by zero") || msg.contains("divisor of zero") {
        return "ZeroDivisionError: integer division or modulo by zero".into();
    }
    if msg.starts_with("assertion failed") {
        return "AssertionError".into();
    }
    if msg.contains("key not found") {
        return "KeyError".into();
    }
    format!("RuntimeError: {}", msg)
}

/// Call first in `main`: Rust panics are reported as Python exceptions.
pub fn init() {
    std::panic::set_hook(Box::new(|info| {
        let msg = if let Some(s) = info.payload().downcast_ref::<&str>() {
            s.to_string()
        } else if let Some(s) = info.payload().downcast_ref::<String>() {
            s.clone()
        } else {
            "panic".to_string()
        };
        let _ = std::io::stdout().flush();
        eprintln!("Traceback (most recent call last):");
        eprintln!("{}", exception_of(&msg));
        std::process::exit(1);
    }));
}

// ------------------------------------------------------------------ printing

/// Python's `str()` / `repr()` of a value.
pub trait Py {
    fn fmt_repr(&self, out: &mut String);
    fn fmt_str(&self, out: &mut String) {
        self.fmt_repr(out)
    }
}

impl Py for i64 {
    fn fmt_repr(&self, out: &mut String) {
        out.push_str(&self.to_string())
    }
}

impl Py for f64 {
    fn fmt_repr(&self, out: &mut String) {
        out.push_str(&float_repr(*self))
    }
}

impl Py for bool {
    fn fmt_repr(&self, out: &mut String) {
        out.push_str(if *self { "True" } else { "False" })
    }
}

impl Py for () {
    fn fmt_repr(&self, out: &mut String) {
        out.push_str("None")
    }
}

impl Py for str {
    fn fmt_repr(&self, out: &mut String) {
        out.push_str(&str_repr(self))
    }
    fn fmt_str(&self, out: &mut String) {
        out.push_str(self)
    }
}

impl Py for String {
    fn fmt_repr(&self, out: &mut String) {
        self.as_str().fmt_repr(out)
    }
    fn fmt_str(&self, out: &mut String) {
        out.push_str(self)
    }
}

impl<T: Py + ?Sized> Py for &T {
    fn fmt_repr(&self, out: &mut String) {
        (**self).fmt_repr(out)
    }
    fn fmt_str(&self, out: &mut String) {
        (**self).fmt_str(out)
    }
}

impl<T: Py + ?Sized> Py for &mut T {
    fn fmt_repr(&self, out: &mut String) {
        (**self).fmt_repr(out)
    }
    fn fmt_str(&self, out: &mut String) {
        (**self).fmt_str(out)
    }
}

impl<T: Py> Py for Option<T> {
    fn fmt_repr(&self, out: &mut String) {
        match self {
            Some(x) => x.fmt_repr(out),
            None => out.push_str("None"),
        }
    }
    fn fmt_str(&self, out: &mut String) {
        match self {
            Some(x) => x.fmt_str(out),
            None => out.push_str("None"),
        }
    }
}

impl<T: Py + ?Sized> Py for Box<T> {
    fn fmt_repr(&self, out: &mut String) {
        (**self).fmt_repr(out)
    }
    fn fmt_str(&self, out: &mut String) {
        (**self).fmt_str(out)
    }
}

impl<T: Py> Py for [T] {
    fn fmt_repr(&self, out: &mut String) {
        out.push('[');
        for (i, x) in self.iter().enumerate() {
            if i > 0 {
                out.push_str(", ");
            }
            x.fmt_repr(out);
        }
        out.push(']');
    }
}

impl<T: Py> Py for Vec<T> {
    fn fmt_repr(&self, out: &mut String) {
        self.as_slice().fmt_repr(out)
    }
}

impl<K: Py, V: Py> Py for IndexMap<K, V> {
    fn fmt_repr(&self, out: &mut String) {
        out.push('{');
        for (i, (k, v)) in self.iter().enumerate() {
            if i > 0 {
                out.push_str(", ");
            }
            k.fmt_repr(out);
            out.push_str(": ");
            v.fmt_repr(out);
        }
        out.push('}');
    }
}

impl<T: Py> Py for IndexSet<T> {
    fn fmt_repr(&self, out: &mut String) {
        if self.is_empty() {
            out.push_str("set()");
            return;
        }
        out.push('{');
        for (i, x) in self.iter().enumerate() {
            if i > 0 {
                out.push_str(", ");
            }
            x.fmt_repr(out);
        }
        out.push('}');
    }
}

macro_rules! tuple_py {
    ($($n:tt $t:ident),+) => {
        impl<$($t: Py),+> Py for ($($t,)+) {
            fn fmt_repr(&self, out: &mut String) {
                out.push('(');
                $(
                    if $n > 0 { out.push_str(", "); }
                    self.$n.fmt_repr(out);
                )+
                if [$($n),+].len() == 1 { out.push(','); }
                out.push(')');
            }
        }
    };
}
tuple_py!(0 A);
tuple_py!(0 A, 1 B);
tuple_py!(0 A, 1 B, 2 C);
tuple_py!(0 A, 1 B, 2 C, 3 D);
tuple_py!(0 A, 1 B, 2 C, 3 D, 4 E);
tuple_py!(0 A, 1 B, 2 C, 3 D, 4 E, 5 F);

/// `{}` shows `str(x)`; width and alignment apply to the whole text.
pub struct S<'a, T: ?Sized>(pub &'a T);
/// `{}` shows `repr(x)`.
pub struct R<'a, T: ?Sized>(pub &'a T);

impl<T: Py + ?Sized> fmt::Display for S<'_, T> {
    fn fmt(&self, f: &mut fmt::Formatter) -> fmt::Result {
        let mut s = String::new();
        self.0.fmt_str(&mut s);
        f.pad(&s)
    }
}

impl<T: Py + ?Sized> fmt::Display for R<'_, T> {
    fn fmt(&self, f: &mut fmt::Formatter) -> fmt::Result {
        let mut s = String::new();
        self.0.fmt_repr(&mut s);
        f.pad(&s)
    }
}

/// `str(x)` for display: `println!("{}", pyrt::s(&x))`
pub fn s<T: Py + ?Sized>(x: &T) -> S<'_, T> {
    S(x)
}

/// `repr(x)` for display
pub fn r<T: Py + ?Sized>(x: &T) -> R<'_, T> {
    R(x)
}

pub fn str<T: Py + ?Sized>(x: &T) -> String {
    let mut s = String::new();
    x.fmt_str(&mut s);
    s
}

pub fn repr<T: Py + ?Sized>(x: &T) -> String {
    let mut s = String::new();
    x.fmt_repr(&mut s);
    s
}

/// Python's shortest round-trip `repr(float)`.
pub fn float_repr(x: f64) -> String {
    if x.is_nan() {
        return "nan".into();
    }
    if x.is_infinite() {
        return if x > 0.0 { "inf".into() } else { "-inf".into() };
    }
    if x == 0.0 {
        return if x.is_sign_negative() { "-0.0".into() } else { "0.0".into() };
    }
    let e = format!("{:e}", x);
    let (mant, exp) = e.split_once('e').unwrap();
    let exp: i32 = exp.parse().unwrap();
    let neg = mant.starts_with('-');
    let digits: String = mant.chars().filter(|c| c.is_ascii_digit()).collect();
    let mut out = String::new();
    if neg {
        out.push('-');
    }
    if (-4..16).contains(&exp) {
        let dp = exp + 1;
        if dp <= 0 {
            out += "0.";
            out += &"0".repeat((-dp) as usize);
            out += &digits;
        } else if dp as usize >= digits.len() {
            out += &digits;
            out += &"0".repeat(dp as usize - digits.len());
            out += ".0";
        } else {
            out += &digits[..dp as usize];
            out.push('.');
            out += &digits[dp as usize..];
        }
    } else {
        out += &digits[..1];
        if digits.len() > 1 {
            out.push('.');
            out += &digits[1..];
        }
        out += &format!("e{}{:02}", if exp < 0 { '-' } else { '+' }, exp.abs());
    }
    out
}

pub fn str_repr(s: &str) -> String {
    let q = if s.contains('\'') && !s.contains('"') { '"' } else { '\'' };
    let mut out = String::new();
    out.push(q);
    for c in s.chars() {
        match c {
            '\\' => out += "\\\\",
            '\n' => out += "\\n",
            '\r' => out += "\\r",
            '\t' => out += "\\t",
            c if c == q => {
                out.push('\\');
                out.push(c)
            }
            c if (c as u32) < 0x20 || (0x7f..=0xa0).contains(&(c as u32)) || c as u32 == 0xad => {
                out += &format!("\\x{:02x}", c as u32)
            }
            c => out.push(c),
        }
    }
    out.push(q);
    out
}

/// A value with a format spec: `f"{x:,}"` where Rust's format differs.
pub fn fmt<T: Fmt + ?Sized>(x: &T, spec: &str) -> String {
    let sp = spec::Spec::parse(spec)
        .unwrap_or_else(|| raise("ValueError", &format!("Invalid format specifier '{}'", spec)));
    x.fmt_spec(&sp)
}

pub trait Fmt {
    fn fmt_spec(&self, sp: &spec::Spec) -> String;
}

impl Fmt for i64 {
    fn fmt_spec(&self, sp: &spec::Spec) -> String {
        spec::format_int(*self, sp)
    }
}

impl Fmt for f64 {
    fn fmt_spec(&self, sp: &spec::Spec) -> String {
        spec::format_float(*self, sp)
    }
}

impl Fmt for str {
    fn fmt_spec(&self, sp: &spec::Spec) -> String {
        spec::format_str(self, sp)
    }
}

impl Fmt for String {
    fn fmt_spec(&self, sp: &spec::Spec) -> String {
        spec::format_str(self, sp)
    }
}

impl<T: Fmt + ?Sized> Fmt for &T {
    fn fmt_spec(&self, sp: &spec::Spec) -> String {
        (**self).fmt_spec(sp)
    }
}

// ------------------------------------------------------------------ numbers

/// `a // b` on ints
pub fn floordiv(a: i64, b: i64) -> i64 {
    if b == 0 {
        raise("ZeroDivisionError", "integer division or modulo by zero");
    }
    let q = a.checked_div(b).unwrap_or_else(|| panic!("attempt to divide with overflow"));
    if (a % b != 0) && ((a < 0) != (b < 0)) {
        q - 1
    } else {
        q
    }
}

/// `a % b` on ints (the result has the sign of `b`)
pub fn modulo(a: i64, b: i64) -> i64 {
    if b == 0 {
        raise("ZeroDivisionError", "integer modulo by zero");
    }
    let r = a.wrapping_rem(b);
    if r != 0 && ((r < 0) != (b < 0)) {
        r + b
    } else {
        r
    }
}

/// `a / b` (true division)
pub fn div(a: f64, b: f64) -> f64 {
    if b == 0.0 {
        raise("ZeroDivisionError", "division by zero");
    }
    a / b
}

/// `a // b` on floats
pub fn ffloordiv(a: f64, b: f64) -> f64 {
    if b == 0.0 {
        raise("ZeroDivisionError", "float floor division by zero");
    }
    let m = a % b;
    let mut d = (a - m) / b;
    if m != 0.0 && ((b < 0.0) != (m < 0.0)) {
        d -= 1.0;
    }
    if d != 0.0 {
        let f = d.floor();
        if d - f > 0.5 {
            f + 1.0
        } else {
            f
        }
    } else {
        0.0f64.copysign(a / b)
    }
}

/// `a % b` on floats
pub fn fmod(a: f64, b: f64) -> f64 {
    if b == 0.0 {
        raise("ZeroDivisionError", "float modulo by zero");
    }
    let mut m = a % b;
    if m != 0.0 {
        if (b < 0.0) != (m < 0.0) {
            m += b;
        }
    } else {
        m = 0.0f64.copysign(b);
    }
    m
}

/// `a ** b` on ints (b ≥ 0)
pub fn ipow(a: i64, b: i64) -> i64 {
    if b < 0 {
        raise("ValueError", "py2rs: int ** negative int gives a float; use a float base");
    }
    let e = u32::try_from(b).unwrap_or_else(|_| panic!("attempt to multiply with overflow"));
    a.checked_pow(e).unwrap_or_else(|| panic!("attempt to multiply with overflow"))
}

/// `a ** b` on floats
pub fn fpow(a: f64, b: f64) -> f64 {
    if a == 0.0 && b < 0.0 {
        raise("ZeroDivisionError", "zero to a negative power");
    }
    if a < 0.0 && b.is_finite() && b.fract() != 0.0 {
        raise("ValueError", "py2rs: a negative number to a fractional power is complex in Python");
    }
    let r = a.powf(b);
    if r.is_infinite() && a.is_finite() && b.is_finite() {
        raise("OverflowError", "(34, 'Result too large')");
    }
    r
}

/// `pow(a, b, m)`
pub fn powmod(a: i64, b: i64, m: i64) -> i64 {
    if m == 0 {
        raise("ValueError", "pow() 3rd argument cannot be 0");
    }
    if b < 0 {
        raise("ValueError", "py2rs: negative exponent in pow(a, b, m) is not supported");
    }
    let mm = m as i128;
    let (mut r, mut base, mut e) = (1i128, (a as i128).rem_euclid(mm), b);
    while e > 0 {
        if e & 1 == 1 {
            r = r * base % mm;
        }
        base = base * base % mm;
        e >>= 1;
    }
    modulo(r as i64, m)
}

/// `a << b`
pub fn shl(a: i64, b: i64) -> i64 {
    if b < 0 {
        raise("ValueError", "negative shift count");
    }
    if a == 0 {
        return 0;
    }
    if b >= 64 || (a << b) >> b != a {
        panic!("attempt to shift left with overflow");
    }
    a << b
}

/// `a >> b`
pub fn shr(a: i64, b: i64) -> i64 {
    if b < 0 {
        raise("ValueError", "negative shift count");
    }
    if b >= 64 {
        return if a < 0 { -1 } else { 0 };
    }
    a >> b
}

/// `int(x)` for a float
pub fn int_float(x: f64) -> i64 {
    if x.is_nan() {
        raise("ValueError", "cannot convert float NaN to integer");
    }
    if x.is_infinite() {
        raise("OverflowError", "cannot convert float infinity to integer");
    }
    let t = x.trunc();
    if !(-9.223372036854775808e18..9.223372036854775808e18).contains(&t) {
        panic!("attempt to convert with overflow");
    }
    t as i64
}

/// `round(x)`
pub fn round(x: f64) -> i64 {
    int_float(x.round_ties_even())
}

/// `round(x, n)`
pub fn round2(x: f64, n: i64) -> f64 {
    if !x.is_finite() {
        return x;
    }
    if n >= 0 {
        if n > 300 {
            return x;
        }
        format!("{:.*}", n as usize, x).parse().unwrap()
    } else {
        let m = 10f64.powi((-n).min(308) as i32);
        (x / m).round_ties_even() * m
    }
}

/// Python's `sum()` of floats (Neumaier compensated, CPython ≥ 3.12)
pub fn sum_f64<I: IntoIterator<Item = f64>>(it: I) -> f64 {
    let mut f = 0.0f64;
    let mut c = 0.0f64;
    for x in it {
        let t = f + x;
        if f.abs() >= x.abs() {
            c += (f - t) + x;
        } else {
            c += (x - t) + f;
        }
        f = t;
    }
    if c != 0.0 && c.is_finite() {
        f += c;
    }
    f
}

// ------------------------------------------------------------------ indexing

/// A Python index (negative counts from the end) as a Rust index.
pub fn idx(i: i64, len: usize) -> usize {
    let n = len as i64;
    let k = if i < 0 { i + n } else { i };
    if k < 0 || k >= n {
        raise("IndexError", "list index out of range");
    }
    k as usize
}

/// Indices selected by `xs[a:b:c]` (CPython's PySlice_AdjustIndices).
pub fn slice_indices(len: usize, lo: Option<i64>, hi: Option<i64>, step: Option<i64>) -> Vec<usize> {
    let n = len as i64;
    let step = step.unwrap_or(1);
    if step == 0 {
        raise("ValueError", "slice step cannot be zero");
    }
    let adj = |v: Option<i64>, dflt: i64, lo_b: i64, hi_b: i64| -> i64 {
        match v {
            None => dflt,
            Some(mut v) => {
                if v < 0 {
                    v += n;
                    if v < lo_b {
                        v = lo_b;
                    }
                } else if v > hi_b {
                    v = hi_b;
                }
                v
            }
        }
    };
    let (start, stop) = if step > 0 {
        (adj(lo, 0, 0, n), adj(hi, n, 0, n))
    } else {
        (adj(lo, n - 1, -1, n - 1), adj(hi, -1, -1, n - 1))
    };
    let mut out = vec![];
    let mut i = start;
    while (step > 0 && i < stop) || (step < 0 && i > stop) {
        out.push(i as usize);
        i += step;
    }
    out
}

/// `xs[a:b:c]`
pub fn slice<T: Clone>(xs: &[T], lo: Option<i64>, hi: Option<i64>, step: Option<i64>) -> Vec<T> {
    if step.is_none() {
        let n = xs.len() as i64;
        let c = |v: i64| (if v < 0 { (v + n).max(0) } else { v.min(n) }) as usize;
        let a = c(lo.unwrap_or(0));
        let b = c(hi.unwrap_or(n));
        return if a < b { xs[a..b].to_vec() } else { vec![] };
    }
    slice_indices(xs.len(), lo, hi, step).into_iter().map(|i| xs[i].clone()).collect()
}

/// `range(a, b, step)` for a general step
pub fn range(start: i64, stop: i64, step: i64) -> impl DoubleEndedIterator<Item = i64> {
    if step == 0 {
        raise("ValueError", "range() arg 3 must not be zero");
    }
    let (a, b, s) = (start as i128, stop as i128, step as i128);
    let n = if s > 0 {
        if a < b { (b - a + s - 1) / s } else { 0 }
    } else if a > b {
        (a - b - s - 1) / (-s)
    } else {
        0
    };
    (0..n as i64).map(move |k| start + k * step)
}

// ------------------------------------------------------------------ lists

/// `xs.insert(i, x)` (the index is clamped like Python's)
pub fn insert<T>(xs: &mut Vec<T>, i: i64, x: T) {
    let n = xs.len() as i64;
    let k = if i < 0 { (i + n).max(0) } else { i.min(n) };
    xs.insert(k as usize, x);
}

/// `xs.pop(i)`
pub fn pop_at<T>(xs: &mut Vec<T>, i: i64) -> T {
    let n = xs.len() as i64;
    if n == 0 {
        raise("IndexError", "pop from empty list");
    }
    let k = if i < 0 { i + n } else { i };
    if k < 0 || k >= n {
        raise("IndexError", "pop index out of range");
    }
    xs.remove(k as usize)
}

/// `xs.remove(x)`
pub fn remove<T: PartialEq>(xs: &mut Vec<T>, x: &T) {
    match xs.iter().position(|e| e == x) {
        Some(i) => {
            xs.remove(i);
        }
        None => raise("ValueError", "list.remove(x): x not in list"),
    }
}

/// `xs.index(x)`
pub fn index<T: PartialEq + Py>(xs: &[T], x: &T) -> i64 {
    match xs.iter().position(|e| e == x) {
        Some(i) => i as i64,
        None => raise("ValueError", &format!("{} is not in list", repr(x))),
    }
}

/// `xs.count(x)`
pub fn count<T: PartialEq>(xs: &[T], x: &T) -> i64 {
    xs.iter().filter(|e| *e == x).count() as i64
}

/// `xs + ys`
pub fn concat<T: Clone>(a: &[T], b: &[T]) -> Vec<T> {
    let mut v = a.to_vec();
    v.extend_from_slice(b);
    v
}

/// `xs * n`
pub fn repeat<T: Clone>(xs: &[T], n: i64) -> Vec<T> {
    if n <= 0 {
        return vec![];
    }
    let mut v = Vec::with_capacity(xs.len() * n as usize);
    for _ in 0..n {
        v.extend_from_slice(xs);
    }
    v
}

/// `s.remove(x)` on a set
pub fn set_remove<T: std::hash::Hash + Eq, Q: std::hash::Hash + indexmap::Equivalent<T> + Py + ?Sized>(
    s: &mut IndexSet<T>,
    x: &Q,
) {
    if !s.shift_remove(x) {
        raise("KeyError", &repr(x));
    }
}

/// `d.pop(k)`
pub fn dict_pop<K: std::hash::Hash + Eq, Q: std::hash::Hash + indexmap::Equivalent<K> + Py + ?Sized, V>(
    d: &mut IndexMap<K, V>,
    k: &Q,
) -> V {
    match d.shift_remove(k) {
        Some(v) => v,
        None => raise("KeyError", &repr(k)),
    }
}

/// `d.update(o)`
pub fn update<K: std::hash::Hash + Eq + Clone, V: Clone>(d: &mut IndexMap<K, V>, o: &IndexMap<K, V>) {
    for (k, v) in o {
        d.insert(k.clone(), v.clone());
    }
}

// ------------------------------------------------------------------ ordering

/// Python's ordering; floats compare without panicking on NaN.
pub trait PyOrd {
    fn py_cmp(&self, other: &Self) -> Ordering;
}

macro_rules! ord_py {
    ($($t:ty),*) => {$(
        impl PyOrd for $t {
            fn py_cmp(&self, other: &Self) -> Ordering { self.cmp(other) }
        }
    )*};
}
ord_py!(i64, bool, String, str);

impl PyOrd for f64 {
    fn py_cmp(&self, other: &Self) -> Ordering {
        self.partial_cmp(other).unwrap_or(Ordering::Equal)
    }
}

impl<T: PyOrd + ?Sized> PyOrd for &T {
    fn py_cmp(&self, other: &Self) -> Ordering {
        (**self).py_cmp(*other)
    }
}

impl<T: PyOrd> PyOrd for [T] {
    fn py_cmp(&self, other: &Self) -> Ordering {
        for (a, b) in self.iter().zip(other.iter()) {
            match a.py_cmp(b) {
                Ordering::Equal => {}
                o => return o,
            }
        }
        self.len().cmp(&other.len())
    }
}

impl<T: PyOrd> PyOrd for Vec<T> {
    fn py_cmp(&self, other: &Self) -> Ordering {
        self.as_slice().py_cmp(other.as_slice())
    }
}

macro_rules! tuple_ord {
    ($($n:tt $t:ident),+) => {
        impl<$($t: PyOrd),+> PyOrd for ($($t,)+) {
            fn py_cmp(&self, other: &Self) -> Ordering {
                $(
                    match self.$n.py_cmp(&other.$n) {
                        Ordering::Equal => {}
                        o => return o,
                    }
                )+
                Ordering::Equal
            }
        }
    };
}
tuple_ord!(0 A);
tuple_ord!(0 A, 1 B);
tuple_ord!(0 A, 1 B, 2 C);
tuple_ord!(0 A, 1 B, 2 C, 3 D);
tuple_ord!(0 A, 1 B, 2 C, 3 D, 4 E);

/// `xs.sort()` for values without a total order (floats)
pub fn sort<T: PyOrd>(xs: &mut [T]) {
    xs.sort_by(|a, b| a.py_cmp(b));
}

/// `xs.sort(reverse=True)`
pub fn sort_rev<T: PyOrd>(xs: &mut [T]) {
    xs.sort_by(|a, b| b.py_cmp(a));
}

/// `sorted(it)`
pub fn sorted<T: PyOrd, I: IntoIterator<Item = T>>(it: I) -> Vec<T> {
    let mut v: Vec<T> = it.into_iter().collect();
    sort(&mut v);
    v
}

/// `max(it)`: the first of the largest items
pub fn max<T: PyOrd, I: IntoIterator<Item = T>>(it: I) -> T {
    let mut best: Option<T> = None;
    for x in it {
        match &best {
            Some(b) if x.py_cmp(b) != Ordering::Greater => {}
            _ => best = Some(x),
        }
    }
    best.unwrap_or_else(|| raise("ValueError", "max() iterable argument is empty"))
}

/// `min(it)`: the first of the smallest items
pub fn min<T: PyOrd, I: IntoIterator<Item = T>>(it: I) -> T {
    let mut best: Option<T> = None;
    for x in it {
        match &best {
            Some(b) if x.py_cmp(b) != Ordering::Less => {}
            _ => best = Some(x),
        }
    }
    best.unwrap_or_else(|| raise("ValueError", "min() iterable argument is empty"))
}

/// `max(it, key=f)`
pub fn max_by_key<T, K: PyOrd, I: IntoIterator<Item = T>>(it: I, key: impl Fn(&T) -> K) -> T {
    let mut best: Option<(K, T)> = None;
    for x in it {
        let k = key(&x);
        match &best {
            Some((b, _)) if k.py_cmp(b) != Ordering::Greater => {}
            _ => best = Some((k, x)),
        }
    }
    best.unwrap_or_else(|| raise("ValueError", "max() iterable argument is empty")).1
}

/// `min(it, key=f)`
pub fn min_by_key<T, K: PyOrd, I: IntoIterator<Item = T>>(it: I, key: impl Fn(&T) -> K) -> T {
    let mut best: Option<(K, T)> = None;
    for x in it {
        let k = key(&x);
        match &best {
            Some((b, _)) if k.py_cmp(b) != Ordering::Less => {}
            _ => best = Some((k, x)),
        }
    }
    best.unwrap_or_else(|| raise("ValueError", "min() iterable argument is empty")).1
}

/// `max(a, b)` on floats (the first unless the second is larger)
pub fn fmax(a: f64, b: f64) -> f64 {
    if b > a {
        b
    } else {
        a
    }
}

/// `min(a, b)` on floats
pub fn fmin(a: f64, b: f64) -> f64 {
    if b < a {
        b
    } else {
        a
    }
}

// ------------------------------------------------------------------ input

/// `input(prompt)`
pub fn input(prompt: &str) -> String {
    print!("{}", prompt);
    let _ = std::io::stdout().flush();
    let mut s = String::new();
    match std::io::stdin().lock().read_line(&mut s) {
        Ok(0) | Err(_) => raise("EOFError", "EOF when reading a line"),
        Ok(_) => {
            if s.ends_with('\n') {
                s.pop();
                if s.ends_with('\r') {
                    s.pop();
                }
            }
            s
        }
    }
}

/// `sorted(it, reverse=True)`
pub fn sorted_rev<T: PyOrd, I: IntoIterator<Item = T>>(it: I) -> Vec<T> {
    let mut v: Vec<T> = it.into_iter().collect();
    sort_rev(&mut v);
    v
}

/// `xs.sort(key=f)`
pub fn sort_by_key<T, K: PyOrd>(xs: &mut [T], key: impl Fn(&T) -> K) {
    xs.sort_by(|a, b| key(a).py_cmp(&key(b)));
}

/// `xs.sort(key=f, reverse=True)`
pub fn sort_by_key_rev<T, K: PyOrd>(xs: &mut [T], key: impl Fn(&T) -> K) {
    xs.sort_by(|a, b| key(b).py_cmp(&key(a)));
}

/// `sorted(it, key=f)`
pub fn sorted_by_key<T, K: PyOrd, I: IntoIterator<Item = T>>(it: I, key: impl Fn(&T) -> K) -> Vec<T> {
    let mut v: Vec<T> = it.into_iter().collect();
    sort_by_key(&mut v, key);
    v
}

/// `sorted(it, key=f, reverse=True)`
pub fn sorted_by_key_rev<T, K: PyOrd, I: IntoIterator<Item = T>>(it: I, key: impl Fn(&T) -> K) -> Vec<T> {
    let mut v: Vec<T> = it.into_iter().collect();
    sort_by_key_rev(&mut v, key);
    v
}
